// QS Studio - QS effect patches (65 bytes): five configurations, each with its own parameter layout.
// Layout from the Alesis "QS6,7,8,R MIDI SYSEX SPECIFICATION", EFFECT DATA FORMAT (core/qs_effects_table.inc,
// generated by tools/gen_effects.py); value names from the QS6 reference manual, Chapter 7 (Editing Effects).
#pragma once
#include <optional>
#include <string>

#include "qs_sysex.h"

namespace qs {

struct EffectParam {
    const char* section;  // "Pitch Send 1", "Reverb Send 1", "Equalizer", "Modulation"...
    const char* name;
    int send;             // effect send (bus) 0-3 for opcode 10, -1 when not per send
    int func, page, pot;  // opcode 10 addressing, mode 3 (Effects)
    int offset, limit;    // displayed = raw + offset
    int lowBit, bits;
    int condIndex;        // -1, or the index of the type parameter this one depends on
    int condMask;         // bit n set: shown when that type parameter's raw value is n
};

struct EffectConfigDef {
    const char* specName;
    const EffectParam* params;
    int count;
};

constexpr int kEffectConfigs = 5;
const EffectParam& effectConfigParam();  // "Effect configuration" (func 2, page 0, pot 0)
const EffectConfigDef& effectConfig(int config);
const char* effectConfigName(int config);  // manual's names: "1 Reverb", "2 Reverbs", "Lezlie and Reverb", ...

// Text for a value ("Plate 1", "Stereo chorus", "+3 dB"...). "" means show the number. config is needed for the
// modulation destinations, which differ per configuration.
std::string effectValueText(const EffectParam& p, int raw, int config = -1);
// Display name without the "Send n " prefix (the section already says which send).
std::string effectShortName(const EffectParam& p);

class Effects {
public:
    Effects() : data(kEffectsBytes, 0) {}
    static std::optional<Effects> fromDump(const Bytes& msg);  // opcode 06 or 08
    static Effects fromData(const Bytes& data);

    int config() const;           // 0-4
    void setConfig(int config);   // clears nothing: the QS keeps other values too
    int raw(const EffectParam& p) const;
    void setRaw(const EffectParam& p, int raw);
    bool visible(int config, int index) const;  // false when the parameter belongs to another effect type

    Bytes userDump(int number) const;  // opcode 06, 0-127
    Bytes editDump(int edit) const;    // opcode 08: 0 Program mode, 1 Mix mode
    const Bytes& bytes() const { return data; }

private:
    Bytes data;
};

Bytes effectsRequest(int number);      // opcode 07
Bytes editEffectsRequest(int edit);    // opcode 09
Bytes effectParamEdit(const EffectParam& p, int value);  // opcode 10, mode 3; displayed value

}  // namespace qs
